fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // If keepends = false, split on '\n' removing '\n'.
            // If keepends = true, split but retain '\n' at end of each line except possibly last.
            if keepends {
                // We do a manual split preserving '\n'.
                let mut lines = Vec::new();
                let mut start = 0;
                let s_bytes = s.as_bytes();
                for (i, &b) in s_bytes.iter().enumerate() {
                    if b == b'\n' {
                        // slice from start to i+1 to keep \n
                        let line = &s[start..=i];
                        lines.push(line.to_string());
                        start = i + 1;
                    }
                }
                // Add any trailing part after last '\n' (may be empty)
                if start < s.len() {
                    lines.push(s[start..].to_string());
                } else if start == s.len() {
                    // The string ended with '\n', so add empty string as last line
                    lines.push(String::new());
                }

                // lines is guaranteed non-empty (at least one line)
                lines
            } else {
                // Simple split on '\n', excluding it
                // This never returns empty Vec; split on empty string yields one element
                s.split('\n').map(|line| line.to_string()).collect()
            }
        })
        .collect()
}